// Control de rangos fisiológicos y verificación de consistencia clínica
const rows = $input.all();
const validated = [];
const anomalies = [];

for (const item of rows) {
  const d = item.json;
  let isValid = true;
  let reason = '';

  if (d.presion_diastolica && d.presion_sistolica && d.presion_diastolica >= d.presion_sistolica) {
    isValid = false;
    reason = 'Inconsistencia: PA diastolica >= sistolica';
  }
  if (d.hba1c && (d.hba1c < 3.0 || d.hba1c > 20.0)) {
    isValid = false;
    reason = 'HbA1c fuera de rango biologico (3.0 - 20.0%)';
  }
  if (d.glucosa && (d.glucosa < 30 || d.glucosa > 600)) {
    isValid = false;
    reason = 'Glucosa fuera de rango fisiologico (30 - 600 mg/dL)';
  }

  if (isValid) {
    validated.push({ json: { ...d, quality_status: 'VALIDADO' } });
  } else {
    anomalies.push({ json: { ...d, quality_status: 'ANOMALIA', reason } });
  }
}

return { validated, anomalies };
